import {writingDetailHeading} from './writing-catalog.mjs';
import {esc,icon,download,formatDate} from './ui.mjs';
import {withStableView} from './view-stability.mjs';
import {mountWritingJobPanel} from './writing-job-panel.mjs';
let active=null;
const fresh=()=>({title:'',audience:'',purpose:'',introduction:'本问卷仅用于研究资料整理，匿名自愿参与，请勿填写姓名、联系方式或其他敏感信息。',questions:[],step:0});
const question=()=>({id:crypto.randomUUID(),type:'single',title:'',options:['选项一','选项二'],required:true});
// AI results may carry verbal Likert options although published answers use 1–5.
// Retain the real endpoint wording in the question; never infer missing labels.
export function aiQuestionnaireScaleTitle(value,options){
 const title=String(value??'').trim();
 if(!Array.isArray(options)||options.length!==5||options.some(option=>typeof option!=='string'||!option.trim()))return title;
 const labels=options.map(option=>option.trim());if(new Set(labels).size!==5||labels.every(option=>/^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(option)))return title;
 const normalized=title.normalize('NFKC'),compact=normalized.replace(/\s/g,''),escape=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 const defined=(score,label)=>new RegExp('(?:^|[^0-9])'+score+'\\s*(?:分\\s*)?(?:[=＝:：]|表示|代表|为|是)\\s*[^\\s,，;；)）]+','u').test(normalized)||new RegExp('(?:^|[^0-9])'+score+'(?:分)?'+escape(label.normalize('NFKC').replace(/\s/g,'')),'iu').test(compact);
 const anchors=[[1,labels[0]],[5,labels[4]]].filter(([score,label])=>!defined(score,label)).map(([score,label])=>`${score} 分＝${label}`);if(!anchors.length)return title;
 const result=title+'（'+anchors.join('；')+'）';if(result.length>500)throw Error('量表题目与端点说明合计超过 500 字，请缩短问题后再采用。');return result;
}
export const questionnaireHasWork=()=>Boolean(active?.hasWork());
export const questionnaireRouteGuard=async()=>active?active.routeGuard():true;
export function disposeQuestionnaire(){active?.dispose();active=null;}
export function questionnaireSessionChanged(user){active?.sessionChanged(user);}
export function mountQuestionnaire({container=document.querySelector('.dashboard'),ctx={},draftId,projectId=''}={}){
 disposeQuestionnaire();if(!container)return false;
 const win=container.ownerDocument.defaultView,doc=container.ownerDocument;
 if(!doc.querySelector('link[data-questionnaire-css]')){const link=doc.createElement('link');link.rel='stylesheet';link.href='/workspace/questionnaire.css';link.dataset.questionnaireCss='';doc.head.append(link);}
 let live=true,ownerId=null,item=null,content=fresh(),step=0,revision=0,savedRevision=0,saving=null,timer=null,error='',status='正在连接账户…',library=[],report=null,reportPub='',panel=null,loaded=false,opening=0,scopeRevision=0,downloading=false,observedUserId=undefined;
 const aborts=new Set(),$=selector=>container.querySelector(selector),current=()=>live&&container.isConnected;
 const getSurveyId=()=>new URLSearchParams(win.location.hash.split('?')[1]||'').get('survey')||'';
 async function api(path,data,{keepalive=false}={}){const scope=scopeRevision;const controller=new win.AbortController();aborts.add(controller);const timeout=win.setTimeout(()=>controller.abort(),20000);try{let value;if(ctx.api)value=await ctx.api(path,data,{signal:controller.signal});else{const response=await win.fetch('/api'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal,keepalive});value=await response.json();if(!response.ok)throw Object.assign(Error(value.error||'问卷操作未完成'),{status:response.status});}if(!current()||scope!==scopeRevision)throw Object.assign(Error('页面已切换'),{name:'AbortError'});return value;}finally{win.clearTimeout(timeout);aborts.delete(controller);}}
 function clearPrivate(message){scopeRevision++;opening++;if(timer)win.clearTimeout(timer);timer=null;for(const controller of aborts)controller.abort();panel?.dispose();panel=null;ownerId=null;content=fresh();item=null;library=[];report=null;loaded=false;revision=0;savedRevision=0;step=0;error=message;status='';draw();}
 async function assertIdentity(){const value=await api('/auth/me');if(!value.user?.id||observedUserId!==undefined&&value.user.id!==observedUserId||ownerId&&value.user.id!==ownerId){clearPrivate('登录账户已变化，请重新打开问卷设计。');throw Error('登录账户已变化，旧账户问卷没有写入新账户。');}ownerId=value.user.id;return ownerId;}
 async function readLibrary(){const expectedOwner=ownerId;if(!expectedOwner||observedUserId!==undefined&&observedUserId!==expectedOwner)throw Object.assign(Error('登录账户已变化'),{name:'AbortError'});const result=await api('/questionnaires?expectedUserId='+encodeURIComponent(expectedOwner));if(ownerId!==expectedOwner||observedUserId!==undefined&&observedUserId!==expectedOwner)throw Object.assign(Error('登录账户已变化'),{name:'AbortError'});if(!Array.isArray(result.items))throw Error('问卷列表响应不完整，请重新读取');return result.items;}
 const saveStatus=()=>{if($('#questionnaire-status'))$('#questionnaire-status').textContent=error||status;};
 function changed(){revision++;error='';status='正在保存草稿…';saveStatus();if(timer)win.clearTimeout(timer);timer=win.setTimeout(()=>void save(),700);}
 async function save({keepalive=false}={}){if(!current()||!loaded||!ownerId)return false;if(timer)win.clearTimeout(timer);timer=null;if(saving){await saving;if(!current())return false;return revision===savedRevision?true:save({keepalive});}if(revision===savedRevision)return true;
  const captured=revision,capturedOwner=ownerId,capturedId=item?.id,capturedVersion=item?.version,capturedScope=scopeRevision,data=structuredClone({...content,step});saving=(async()=>{try{await assertIdentity();if(ownerId!==capturedOwner||scopeRevision!==capturedScope)throw Object.assign(Error('页面已切换'),{name:'AbortError'});const result=capturedId?await api('/questionnaires/'+capturedId,{version:capturedVersion,content:data,expectedUserId:capturedOwner},{keepalive}):await api('/questionnaires',{content:data,projectId,expectedUserId:capturedOwner},{keepalive});if(!current())return false;item=result.item;library=[item,...library.filter(row=>row.id!==item.id)];renderLibrary();const currentHash=win.location.hash.split('?')[0],currentSurvey=new URLSearchParams(win.location.hash.split('?')[1]||'').get('survey');if(currentHash==='#tool/questionnaire'&&(capturedId?currentSurvey===capturedId:!currentSurvey))win.history.replaceState(null,'',win.location.pathname+win.location.search+'#tool/questionnaire?survey='+encodeURIComponent(item.id));savedRevision=captured;status=revision===captured?'草稿已保存到账户':'正在保存更新…';error='';saveStatus();updatePublicationHint();return true;}catch(e){if(current()&&e.name!=='AbortError'){error=e.status===409?(/登录账户已变化/.test(e.message)?'登录账户已变化，当前内容未写入其他账户。请切回原账户后重试保存。':'草稿在其他页面已更新。当前编辑仍保留，请先导出备份，再重新打开。'):e.status===401?'请登录后保存；当前输入仍保留在页面。':e.message;status='保存未完成';saveStatus();}return false;}finally{saving=null;}})();const result=await saving;if(result&&revision!==savedRevision)return save({keepalive});return result;}
 function snapshot(){return{title:content.title.trim(),profile:{level:'本科',major:'',language:'中文',targetWords:500},requirements:{instructions:`目标人群：${content.audience||'待确认'}\n研究目标：${content.purpose||'待确认'}\n题数优先遵照上述研究目标中的要求，未指定时默认设计 6 道清楚、中性的匿名问题。不得索取姓名、电话、住址、证件、健康等敏感信息。`},materials:[],references:[],outline:[]};}
 function shell(){container.classList.add('creation-page');container.classList.remove('category-view');container.innerHTML=`<div class="questionnaire-space">${writingDetailHeading('questionnaire')}<div class="q-layout"><section class="card q-main"><div class="q-top"><div><span class="q-kicker">QUESTIONNAIRE STUDIO</span><h2>从研究问题，到真实答卷</h2><p>先核对题目，再发布收集。统计结果始终来自实际答卷。</p></div><div class="q-actions"><button class="btn secondary" type="button" data-q-backup>导出草稿备份</button><button class="btn secondary" id="writing-save" type="button">保存草稿</button></div></div><ol class="q-steps" aria-label="问卷设计四步流程">${['创建问卷设计','修改完善问题','发放收集数据','生成分析报告'].map((label,index)=>`<li><button type="button" data-q-step="${index}"><span>${index+1}</span><b>${label}</b></button></li>`).join('')}</ol><p id="questionnaire-status" role="status" aria-live="polite"></p><div id="questionnaire-step"></div><div id="questionnaire-ai" hidden></div></section><aside class="q-side"><section class="card"><h3>我的问卷</h3><button type="button" class="btn secondary" data-q-new>新建问卷</button><div id="questionnaire-library"></div></section><section class="q-note"><span>${icon('shield',21)}</span><h3>匿名 · 自愿 · 最少信息</h3><p>不要索取姓名、手机号、身份证、健康等敏感信息。正式发放前，请核对研究伦理与必要的知情同意。</p><p>答卷只向创建者展示。统计为描述性结果，不代表总体或因果关系。</p></section></aside></div></div>`;
  $('#writing-save').onclick=()=>void save();container.addEventListener('click',click,{signal:listeners.signal});container.addEventListener('input',input,{signal:listeners.signal});container.addEventListener('change',input,{signal:listeners.signal});
 }
 const listeners=new win.AbortController();
 function draw(){if(!current())return;if(!$('#questionnaire-step'))shell();withStableView(container,()=>{
  [...container.querySelectorAll('[data-q-step]')].forEach((button,index)=>{button.classList.toggle('is-active',index===step);const complete=index===0?Boolean(content.title.trim()):index===1?!validation():index===2?Boolean(item?.publications.length):Boolean(report?.total);button.classList.toggle('is-complete',index!==step&&complete);button.setAttribute('aria-current',index===step?'step':'false');button.querySelector('span').innerHTML=index!==step&&complete?icon('check',17):String(index+1);});saveStatus();
  renderLibrary();
  if(!loaded){$('#questionnaire-step').innerHTML=`<div class="q-empty">${error?`<p role="alert">${esc(error)}</p><a class="btn primary" href="/auth.html?mode=login&next=${encodeURIComponent('/workspace.html#tool/questionnaire')}">登录后管理问卷</a>`:'<p>正在读取账户问卷…</p>'}</div>`;return;}
  if(step===0)$('#questionnaire-step').innerHTML=`<form id="writing-form" class="q-form"><div class="q-section-title"><span>01</span><div><h3>明确这次调查想了解什么</h3><p>可以手动创建问题，也可以让 AI 起草，再逐项核对。</p></div></div><label for="writing-title">问卷主题 <em>必填</em></label><input id="writing-title" data-q-field="title" maxlength="200" required value="${esc(content.title)}" placeholder="例如：高校图书馆数字阅读服务体验调查"><label for="q-audience">目标人群（可选）</label><input id="q-audience" data-q-field="audience" maxlength="300" value="${esc(content.audience)}" placeholder="例如：在校本科生"><label for="q-purpose">研究目标与维度（可选）</label><textarea id="q-purpose" data-q-field="purpose" rows="4" maxlength="2000" placeholder="希望了解哪些体验、行为或需求？">${esc(content.purpose)}</textarea><label for="q-introduction">答题说明与知情同意</label><textarea id="q-introduction" data-q-field="introduction" rows="3" maxlength="2000">${esc(content.introduction)}</textarea><div class="q-actions"><button class="btn secondary" type="button" data-q-ai>${icon('pen',16)} AI 起草问卷</button><button class="btn primary" type="button" data-q-next>下一步：完善问题 →</button></div></form>`;
  if(step===1)$('#questionnaire-step').innerHTML=`<div class="q-section-title"><span>02</span><div><h3>让每一个问题都清楚、可回答</h3><p>支持单选、多选、五点量表与开放题，最多 40 道。</p></div></div><div class="q-editor">${content.questions.map((q,index)=>`<fieldset class="q-question" data-q-question="${esc(q.id)}"><legend><b>问题 ${index+1}</b><button class="q-link" type="button" data-q-remove="${esc(q.id)}">移除</button></legend><div class="q-question-meta"><select data-q-question-type="${esc(q.id)}" aria-label="第 ${index+1} 题类型">${[['single','单选题'],['multiple','多选题'],['scale','五点量表'],['text','开放题']].map(([value,label])=>`<option value="${value}" ${q.type===value?'selected':''}>${label}</option>`).join('')}</select><label><input type="checkbox" data-q-required="${esc(q.id)}" ${q.required?'checked':''}> 必填</label></div><label for="q-title-${esc(q.id)}">问题标题</label><input id="q-title-${esc(q.id)}" data-q-question-title="${esc(q.id)}" maxlength="500" value="${esc(q.title)}" placeholder="避免诱导、双重问题与敏感信息">${['single','multiple'].includes(q.type)?`<label for="q-options-${esc(q.id)}">选项（每行一个，2～20 个）</label><textarea id="q-options-${esc(q.id)}" data-q-options="${esc(q.id)}" rows="${Math.min(6,q.options.length+1)}" maxlength="3200">${esc(q.options.join('\n'))}</textarea>`:q.type==='scale'?'<p class="q-muted">固定 1～5 分，请在题目中说明两端含义，例如：1 非常不满意，5 非常满意。</p>':'<p class="q-muted">答题者最多输入 2,000 字，请勿索取个人敏感信息。</p>'}</fieldset>`).join('')||'<div class="q-empty"><p>还没有问题。先添加一道，或用 AI 生成可编辑草稿。</p></div>'}</div><div class="q-actions"><button class="btn secondary" type="button" data-q-add ${content.questions.length>=40?'disabled':''}>＋ 添加问题</button><button class="btn secondary" type="button" data-q-ai>AI 起草问卷</button><button class="btn primary" type="button" data-q-next>下一步：发布收集 →</button></div>`;
  if(step===2)drawPublish();if(step===3)drawReport();
 },{restoreFocus:true});}
 function renderLibrary(){const libraryNode=$('#questionnaire-library');libraryNode.innerHTML=library.length?library.map(row=>`<button type="button" data-q-open="${esc(row.id)}"><b>${esc(row.content.title||'未命名问卷')}</b><small>${formatDate(row.updatedAt)} · ${row.publications[0]?.responseCount||0} 份最新答卷</small></button>`).join(''):'<p class="q-muted">保存后会出现在这里，可跨设备继续。</p>';}
 function validation(){if(!content.title.trim())return'请先填写问卷主题。';if(!content.questions.length)return'请至少添加一道问题。';for(const q of content.questions){if(!q.title.trim())return'请填写每道题的问题标题。';if(['single','multiple'].includes(q.type)&&(q.options.length<2||q.options.some(v=>!v.trim())||new Set(q.options).size!==q.options.length))return'选择题需要至少两个不同的非空选项。';}return'';}
 function updatePublicationHint(){const node=$('#q-publication-hint');if(node){const pub=item?.publications.find(row=>row.status==='open');node.textContent=pub&&pub.matchesDraft===false?'当前草稿已有修改。已发布链接仍使用旧版本，重新发布后将关闭旧链接并生成新链接。':'发布时固定问题版本，之后修改草稿不会改变已收到的答卷。';}}
 function drawPublish(){const pub=item?.publications.find(row=>row.status==='open');$('#questionnaire-step').innerHTML=`<div class="q-section-title"><span>03</span><div><h3>确认问题，再开始收集</h3><p id="q-publication-hint"></p></div></div><div class="q-publish-summary"><div><small>问卷主题</small><b>${esc(content.title||'未填写')}</b></div><div><small>当前问题</small><b>${content.questions.length} 道</b></div><div><small>最新答卷</small><b>${item?.publications[0]?.responseCount||0} 份</b></div></div><div class="q-notice">问卷采用匿名自愿填写，不收集登录身份。每个浏览器标识对同一发布版本仅可提交一次；清除浏览器数据或换设备仍可能重复，正式研究请结合抽样与质控。</div>${pub?`<label for="q-public-url">公开填写链接</label><input id="q-public-url" readonly value="${esc(new URL(pub.url,win.location.origin).href)}"><div class="q-actions"><button class="btn secondary" type="button" data-q-copy>复制链接</button><a class="btn secondary" target="_blank" rel="noopener" href="${esc(pub.url)}">打开填写页 ↗</a><button class="btn secondary" type="button" data-q-close>停止收集</button></div>`:'<div class="q-empty"><p>尚未开放收集。发布成功后会生成可直接填写的独立链接。</p></div>'}<label class="q-confirm"><input id="q-publish-confirm" type="checkbox"> 我已核对题目与知情同意，不收集敏感信息，并确认发布当前问题版本。</label><div class="q-actions"><button class="btn primary" type="button" data-q-publish>${pub?'重新发布当前版本':'确认发布问卷'}</button><button class="btn secondary" type="button" data-q-next>查看真实答卷统计 →</button></div>`;updatePublicationHint();}
 function drawReport(){const pubs=item?.publications||[];$('#questionnaire-step').innerHTML=`<div class="q-section-title"><span>04</span><div><h3>只分析实际收到的答卷</h3><p>题目分布、有效作答数与量表均值；不生成虚构样本。</p></div></div><div class="q-actions"><label>发布版本<select id="q-report-version">${pubs.map(pub=>`<option value="${esc(pub.id)}" ${pub.id===(reportPub||pubs[0]?.id)?'selected':''}>版本 ${pub.version} · ${pub.responseCount} 份 · ${pub.status==='open'?'收集中':'已关闭'}</option>`).join('')||'<option value="">尚未发布</option>'}</select></label><button class="btn secondary" type="button" data-q-report>更新分析报告</button>${report?.total?`<button class="btn secondary" type="button" data-q-csv ${downloading?'disabled':''}>导出真实答卷 CSV</button><button class="btn primary" type="button" data-q-report-export>导出分析报告 TXT</button>`:''}</div>${!report?.total?'<div class="q-empty"><span>'+icon('chart',36)+'</span><h3>暂时没有可分析的答卷</h3><p>发布问卷并收到真实答卷后，再更新报告；这里不会填入示例数据。</p></div>':`<div class="q-report-total"><b>${report.total}</b><span>本版本实际答卷</span><small>统计时间 ${formatDate(report.generatedAt)}</small></div>${report.questions.map((q,index)=>`<section class="q-report-question"><h4>${index+1}. ${esc(q.title)}</h4><p class="q-muted">作答 ${q.answered} · 未答 ${q.missing}${q.mean!==undefined?' · 量表均值 '+(q.mean??'—'):''}</p>${q.distribution?`<div class="q-distribution">${q.distribution.map(row=>`<div><span>${esc(row.option)}</span><meter min="0" max="100" value="${row.percent}" aria-label="${esc(row.option)} ${row.count} 人"></meter><b>${row.count} · ${row.percent}%</b></div>`).join('')}</div>`:`<ul class="q-text-answers">${q.textAnswers.map(value=>`<li>${esc(value)}</li>`).join('')||'<li>暂无文字回答</li>'}</ul>${q.textAnswersLimited?'<p>页面仅展示最新 50 条，完整答卷请导出 CSV。</p>':''}`}${q.note?`<p class="q-muted">${esc(q.note)}</p>`:''}</section>`).join('')}<div class="q-notice">${esc(report.limitations)}</div>`}`;}
 async function downloadResponses(){
  if(downloading||!item||!report?.total)return;
  const capturedId=item.id,capturedOwner=ownerId,capturedOpening=opening,capturedScope=scopeRevision,publication=report.publicationId,title=content.title||'问卷';
  const same=()=>current()&&item?.id===capturedId&&ownerId===capturedOwner&&opening===capturedOpening&&scopeRevision===capturedScope;
  const button=$('[data-q-csv]'),controller=new win.AbortController();downloading=true;if(button)button.disabled=true;aborts.add(controller);const timeout=win.setTimeout(()=>controller.abort(),25000);
  try{
   await assertIdentity();if(!same())return;
   const response=await win.fetch('/api/questionnaires/'+encodeURIComponent(capturedId)+'/responses.csv?publication='+encodeURIComponent(publication),{method:'GET',credentials:'same-origin',cache:'no-store',signal:controller.signal});
   if(!same())return;
   if(!response.ok){const value=await response.json().catch(()=>({}));throw Error(value.error||'答卷导出未完成，请稍后重试。');}
   if(!/^text\/csv(?:;|$)/i.test(response.headers.get('Content-Type')||''))throw Error('答卷导出格式不正确，当前报告仍保留，请重试。');
   const bytes=Number(response.headers.get('Content-Length'));if(Number.isFinite(bytes)&&bytes>64*1024*1024)throw Error('答卷文件过大，请联系支持分批导出。');
   const blob=await response.blob();if(blob.size>64*1024*1024)throw Error('答卷文件过大，请联系支持分批导出。');if(!same())return;
   await assertIdentity();if(!same())return;
   const exported=await download(title+'-真实答卷.csv',blob,'text/csv;charset=utf-8',{sourceType:'writing',sourceId:capturedId});if(!same())return;status=exported.message;error='';saveStatus();
  }catch(e){if(same()&&e.name!=='AbortError'){error=e.message||'答卷导出未完成，当前页面与报告仍保留。';saveStatus();}}
  finally{win.clearTimeout(timeout);aborts.delete(controller);downloading=false;if(button?.isConnected)button.disabled=false;}
 }
 async function loadReport(){if(!item)return;const capturedId=item.id,capturedOpening=opening;const pub=$('#q-report-version')?.value||reportPub||item.publications[0]?.id;if(!pub){report=null;draw();return;}reportPub=pub;await assertIdentity();const result=await api('/questionnaires/'+capturedId+'/report?publication='+encodeURIComponent(pub));if(!current()||item?.id!==capturedId||opening!==capturedOpening)return;const freshItem=(await api('/questionnaires/'+capturedId)).item;if(!current()||item?.id!==capturedId||opening!==capturedOpening)return;report=result.report;item=freshItem;draw();}
 async function openSurvey(id){if(!await save())return;const token=++opening;try{await assertIdentity();const result=await api('/questionnaires/'+encodeURIComponent(id));if(token!==opening)return;panel?.dispose();panel=null;item=result.item;if(win.location.hash.startsWith('#tool/questionnaire'))win.history.replaceState(null,'',win.location.pathname+win.location.search+'#tool/questionnaire?survey='+encodeURIComponent(item.id));content=structuredClone(item.content);step=content.step||0;revision=0;savedRevision=0;report=null;reportPub='';status='草稿已保存到账户';error='';draw();if(step===3)await loadReport();}catch(e){error=e.message;saveStatus();}}
 function input(event){const target=event.target;if(target.dataset.qField){content[target.dataset.qField]=target.value;changed();return;}const qid=target.dataset.qQuestionTitle||target.dataset.qOptions||target.dataset.qQuestionType||target.dataset.qRequired,q=content.questions.find(value=>value.id===qid);if(!q)return;if(target.dataset.qQuestionTitle)q.title=target.value;if(target.dataset.qOptions)q.options=target.value.split('\n').map(v=>v.trim()).slice(0,20);if(target.dataset.qRequired)q.required=target.checked;if(target.dataset.qQuestionType){q.type=target.value;q.options=q.type==='scale'?['1','2','3','4','5']:q.type==='text'?[]:q.options.length>=2?q.options:['选项一','选项二'];changed();draw();return;}changed();}
 async function go(next){if(next>0&&!content.title.trim()){error='请先填写问卷主题。';saveStatus();return;}if(next>=2){const reason=validation();if(reason){error=reason;saveStatus();return;}}step=next;content.step=step;changed();draw();if(step===3)try{await save();await loadReport();}catch(e){error=e.message;saveStatus();}}
 async function click(event){const button=event.target.closest('button');if(!button||!container.contains(button))return;
  try{if(button.hasAttribute('data-q-backup')){await download((content.title||'问卷草稿')+'-备份.json',JSON.stringify({title:content.title,audience:content.audience,purpose:content.purpose,introduction:content.introduction,questions:content.questions},null,2),'application/json');return;}if(button.dataset.qStep!==undefined)return void await go(Number(button.dataset.qStep));if(button.hasAttribute('data-q-next'))return void await go(Math.min(3,step+1));if(button.dataset.qOpen)return void await openSurvey(button.dataset.qOpen);if(button.hasAttribute('data-q-new')){if(!await save())return;panel?.dispose();panel=null;opening++;content=fresh();item=null;report=null;reportPub='';step=0;revision=0;savedRevision=0;if(win.location.hash.startsWith('#tool/questionnaire'))win.history.replaceState(null,'',win.location.pathname+win.location.search+'#tool/questionnaire');status='新问卷，填写后自动保存到账户';draw();return;}
   if(button.hasAttribute('data-q-add')){if(content.questions.length<40){content.questions.push(question());changed();draw();}return;}if(button.dataset.qRemove){content.questions=content.questions.filter(q=>q.id!==button.dataset.qRemove);changed();draw();return;}
   if(button.hasAttribute('data-q-ai')){if(!content.title.trim())throw Error('请先填写问卷主题。');if(!panel)panel=mountWritingJobPanel({container:$('#questionnaire-ai'),ctx,kind:'questionnaire',operation:'questionnaire',getSnapshot:snapshot,initialState:content.aiState||{},isCurrent:current,onStateChange:state=>{content.aiState=state;changed();},onApply:async output=>{if(!Array.isArray(output.questions)||!output.questions.length)throw Error('没有获得可编辑的问题，请重试。');content.questions=output.questions.slice(0,40).map(q=>({id:crypto.randomUUID(),title:q.type==='scale'?aiQuestionnaireScaleTitle(String(q.title||'').slice(0,500),q.options):String(q.title||'').slice(0,500),type:['single','multiple','scale','text'].includes(q.type)?q.type:'text',options:q.type==='scale'?['1','2','3','4','5']:(q.options||[]).slice(0,20).map(v=>String(v).slice(0,150)),required:q.required===true}));if(output.introduction)content.introduction=String(output.introduction).slice(0,2000);step=1;changed();draw();await save();}});await panel.open();return;}
   if(button.hasAttribute('data-q-publish')){const reason=validation();if(reason)throw Error(reason);if(!$('#q-publish-confirm').checked)throw Error('请先勾选发布确认。');if(!await save())return;const capturedId=item.id,capturedVersion=item.version,capturedOpening=opening;await assertIdentity();const published=(await api('/questionnaires/'+capturedId+'/publish',{version:capturedVersion})).item;if(!current()||item?.id!==capturedId||opening!==capturedOpening)return;const freshLibrary=await readLibrary();if(!current()||item?.id!==capturedId||opening!==capturedOpening)return;item=published;library=freshLibrary;status='已发布，链接可真实填写与收集答卷';draw();return;}
   if(button.hasAttribute('data-q-close')){if(!await save())return;const capturedId=item.id,capturedVersion=item.version,capturedOpening=opening;await assertIdentity();const closed=(await api('/questionnaires/'+capturedId+'/close',{version:capturedVersion})).item;if(!current()||item?.id!==capturedId||opening!==capturedOpening)return;item=closed;status='已停止收集，已有答卷仍保留';draw();return;}
   if(button.hasAttribute('data-q-copy')){await win.navigator.clipboard.writeText($('#q-public-url').value);status='填写链接已复制';saveStatus();return;}if(button.hasAttribute('data-q-csv'))return void await downloadResponses();if(button.hasAttribute('data-q-report'))return void await loadReport();if(button.hasAttribute('data-q-report-export')&&report){await download(content.title+'-真实答卷分析报告.txt',reportText(report));return;}
  }catch(e){if(current()&&e.name!=='AbortError'){error=e.message;saveStatus();}}
 }
 const focus=()=>{if(loaded&&ownerId)void assertIdentity().catch(e=>{if(e.status===401)clearPrivate('登录已失效，请重新登录后查看账户问卷。');});};const hide=()=>{if(doc.hidden)void save({keepalive:true});};const unload=e=>{if(revision!==savedRevision){void save({keepalive:true});e.preventDefault();e.returnValue='';}};
 win.addEventListener('focus',focus);doc.addEventListener('visibilitychange',hide);win.addEventListener('beforeunload',unload);
 const handle={dispose(){if(!live)return;live=false;if(timer)win.clearTimeout(timer);panel?.dispose();for(const controller of aborts)controller.abort();listeners.abort();win.removeEventListener('focus',focus);doc.removeEventListener('visibilitychange',hide);win.removeEventListener('beforeunload',unload);},hasWork:()=>revision!==savedRevision,save,routeGuard:async()=>{if(!loaded||!ownerId)return revision===savedRevision;const ok=await save();if(!ok&&current())ctx.notify?.('问卷草稿尚未保存，请重试保存或导出备份。');return ok;},sessionChanged(user){const nextUserId=user?.id??null,previous=observedUserId,restartInitial=previous===undefined&&ownerId===null&&nextUserId!==null;observedUserId=nextUserId;if(previous===nextUserId)return;if(ownerId!==null&&ownerId===nextUserId)return;clearPrivate(nextUserId===null?'当前已退出登录，请重新登录后查看问卷。':'登录账户已变化，请重新打开问卷设计。');if(restartInitial)void initialize();}};active=handle;
 async function initialize(){const scope=scopeRevision;try{await assertIdentity();if(scope!==scopeRevision)return;const rows=await readLibrary();if(scope!==scopeRevision)return;library=rows;loaded=true;error='';status='填写后自动保存到账户';draw();const id=getSurveyId();if(id)await openSurvey(id);}catch(e){if(current()&&scope===scopeRevision&&e.name!=='AbortError'){error=e.status===401?'请登录后创建、发布与管理账户问卷。':e.message;draw();}}}
 shell();draw();void initialize();return handle;
}
function reportText(report){return `${report.title}\n真实答卷分析报告\n发布版本：${report.version}\n实际答卷：${report.total}\n统计时间：${report.generatedAt}\n\n${report.questions.map((q,index)=>`${index+1}. ${q.title}\n已答 ${q.answered}，未答 ${q.missing}${q.mean!==undefined?'，量表均值 '+(q.mean??'—'):''}\n${q.distribution?q.distribution.map(row=>`${row.option}：${row.count}（${row.percent}%）`).join('\n'):q.textAnswers.map((text,i)=>`${i+1}) ${text}`).join('\n')}${q.note?'\n'+q.note:''}`).join('\n\n')}\n\n${report.limitations}`;}
